From 6fd3511e4d54ab05c4fec54003c0ef9830743c72 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 18:34:41 +0100
Subject: [PATCH] applets/kicker: show where an app comes from when names are
 the same

An app installed from more than one source, like Firefox from the distro
and from Flatpak, showed up as identical items in the app grids and the
search results. Same-named apps now get "(Flatpak)" or "(Snap)" added.

BUG: 500734
---
 applets/kicker/actionlist.cpp         | 14 ++++++++++++++
 applets/kicker/actionlist.h           |  2 ++
 applets/kicker/appentry.cpp           |  9 +++++++++
 applets/kicker/appentry.h             |  3 +++
 applets/kicker/appsmodel.cpp          | 22 ++++++++++++++++++++++
 applets/kicker/runnermatchesmodel.cpp | 11 +++++++++++
 6 files changed, 61 insertions(+)

diff --git a/applets/kicker/actionlist.cpp b/applets/kicker/actionlist.cpp
index db486ea5e2..4344981702 100644
--- a/applets/kicker/actionlist.cpp
+++ b/applets/kicker/actionlist.cpp
@@ -411,6 +411,20 @@ bool handleEditApplicationAction(const QString &actionId, const KService::Ptr &s
 Q_GLOBAL_STATIC(AppStream::Pool, appstreamPool)
 #endif

+QString nameWithInstallSource(const QString &name, const KService::Ptr &service)
+{
+    QString source;
+    if (!service->property<QString>(QStringLiteral("X-Flatpak")).isEmpty()) {
+        source = i18nc("@item where an app was installed from", "Flatpak");
+    } else if (!service->property<QString>(QStringLiteral("X-SnapInstanceName")).isEmpty()) {
+        source = i18nc("@item where an app was installed from", "Snap");
+    } else {
+        return name;
+    }
+
+    return i18nc("@item:inlistbox App name (where it was installed from, e.g. Flatpak)", "%1 (%2)", name, source);
+}
+
 QVariantList appstreamActions(const KService::Ptr &service)
 {
     Q_UNUSED(service)
