diff --git a/applets/kicker/appsmodel.cpp b/applets/kicker/appsmodel.cpp
index a59548571c..963d209076 100644
--- a/applets/kicker/appsmodel.cpp
+++ b/applets/kicker/appsmodel.cpp
@@ -507,6 +507,24 @@ static bool containsSameStorageId(const QList<AbstractEntry *> &entryList, const
     });
 }

+static void showInstallSourceOfSameNamedApps(const QList<AbstractEntry *> &entryList)
+{
+    QHash<QString, QList<AppEntry *>> appsByName;
+    for (AbstractEntry *entry : entryList) {
+        if (entry->type() == AbstractEntry::ApplicationType) {
+            appsByName[entry->name()].append(static_cast<AppEntry *>(entry));
+        }
+    }
+
+    for (const QList<AppEntry *> &apps : std::as_const(appsByName)) {
+        if (apps.size() > 1) {
+            for (AppEntry *app : apps) {
+                app->setShowInstallSource(true);
+            }
+        }
+    }
+}
+
 void AppsModel::refreshInternal()
 {
     if (m_staticEntryList) {
@@ -574,6 +592,8 @@ void AppsModel::refreshInternal()
             }
         }

+        showInstallSourceOfSameNamedApps(m_entryList);
+
         if (m_sorted) {
             sortEntries(m_entryList);
         }
@@ -588,6 +608,8 @@ void AppsModel::refreshInternal()
             }
         }

+        showInstallSourceOfSameNamedApps(m_entryList);
+
         if (m_sorted) {
             sortEntries(m_entryList);
         }
